// Rosco de progreso genérico (usado en Salud y Plan) — pista y arco reales
// del diseño: pista = textDark al 15%, arco = color semántico por tarjeta.
function ProgressRing({ percent = 0, size = 62, strokeWidth = 7, arcColor = colors.ctaGreen }) {
    const clamped = Math.max(0, Math.min(100, percent));
    const r = (size - strokeWidth) / 2;
    const c = size / 2;
    const circumference = 2 * Math.PI * r;
    const dash = (clamped / 100) * circumference;
    return (
        <Svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
            <Circle cx={c} cy={c} r={r} fill="none" stroke={RING_TRACK} strokeWidth={strokeWidth} />
            <Circle
                cx={c}
                cy={c}
                r={r}
                fill="none"
                stroke={arcColor}
                strokeWidth={strokeWidth}
                strokeDasharray={`${dash} ${circumference}`}
                strokeLinecap="round"
                transform={`rotate(-90 ${c} ${c})`}
            />
        </Svg>
    );
}

