// Icono + color por tipo de nudge — compartido entre la vista previa local y
// los nudges reales que devuelva el backend (identificados por nudgeKind).
const NUDGE_VISUALS = {
    fatigue: { icon: <IconFatigueLarge /> },
    academic: { icon: <IconTutorLarge /> },
    boe: { icon: <IconBoeLarge /> },
};

// ─── Definición de los 3 nudges (2.4 a/b/c) ──────────────────────────────────
// Vista previa temporal: en producción cada nudge lo disparará su propio motor
// (fatiga biométrica, estadísticas de rendimiento, monitor BOE de otros bloques).
const NUDGES = {
    fatigue: {
        ...NUDGE_VISUALS.fatigue,
        title: 'Tu nivel de fatiga es alto',
        description:
            'Tu HRV ha bajado y el pulso en reposo está elevado. Tómate 10 minutos de respiración guiada antes de seguir: rendirás más.',
        primaryLabel: 'Hacer pausa de 10 min',
        secondaryLabel: 'Seguir estudiando',
    },
    academic: {
        ...NUDGE_VISUALS.academic,
        title: 'La Ley 39/2015 se te resiste',
        description:
            'Has fallado 6 de las últimas 10 preguntas de este tema. ¿Quieres que el Tutor IA te lo explique en el Aula Virtual?',
        primaryLabel: 'Que me lo explique la IA',
        secondaryLabel: 'Ahora no',
    },
    boe: {
        ...NUDGE_VISUALS.boe,
        title: '¡Alerta BOE!',
        description:
            'El artículo 14 de tu temario ha sido modificado. Haz un mini-test de actualización para no estudiar nada desfasado.',
        primaryLabel: 'Ver el cambio y hacer test',
        secondaryLabel: 'Más tarde',
    },
};

// Ícono confirmado en Figma para el pop-up "TEMARIO DESACTUALIZADO" (10.1) —
// círculo + barra de aviso en naranja, sin círculo de fondo detrás.
function StaleLawsWarningIcon({ size = 48, color = colors.accentOrange }) {
    return (
        <Svg width={size} height={size} viewBox="0 0 48 48">
            <Circle cx={24} cy={24} r={22} stroke={color} strokeWidth={3} fill="none" />
            <Path d="M24 14V27" stroke={color} strokeWidth={3.2} strokeLinecap="round" />
            <Circle cx={24} cy={34} r={1.8} fill={color} />
        </Svg>
    );
}

// ─── Pantalla principal (2.1 Dashboard + 2.2 Acceso rápido) ─────────────────
export default function DashboardScreen({ navigation }) {
    const insets = useSafeAreaInsets();
    const [activeNudge, setActiveNudge] = useState(null); // null | 'fatigue' | 'academic' | 'boe'
    const nudge = activeNudge ? NUDGES[activeNudge] : null;
    const [boeBannerVisible, setBoeBannerVisible] = useState(false);
    const [staleAlertVisible, setStaleAlertVisible] = useState(false);
    const [staleLawsCount, setStaleLawsCount] = useState(0);

    const [summary, setSummary] = useState(null);
    const [planSummary, setPlanSummary] = useState(null);
    const [realNudgeVisible, setRealNudgeVisible] = useState(false);
    const nudgeShownRef = useRef(false);

    const loadData = useCallback(() => {
        let cancelled = false;
        dashboardApi.getSummary().then(({ data }) => {
            if (cancelled || !data) return;
            setSummary(data);
            if (data.nextNudge && !nudgeShownRef.current) {
                nudgeShownRef.current = true;
                setRealNudgeVisible(true);
            }
        });
        planningApi.getSummary().then(({ data }) => {
            if (!cancelled && data) setPlanSummary(data);
        });
        boeApi.getFeed().then(res => {
            if (cancelled || res?.error || !res?.data) return;
            const unread = res.data.totalUnread ?? 0;
            if (unread > 0) {
                setStaleLawsCount(unread);
                if (!_boeAlertShownThisSession) {
                    _boeAlertShownThisSession = true;
                    setStaleAlertVisible(true);
                }
            }
        }).catch(() => {});
        return () => { cancelled = true; };
    }, []);

    useFocusEffect(loadData);

    const displayName = summary?.profile.displayName || 'Opositor';
    const oposicionLine = summary?.profile.oposicion && summary?.profile.especialidad
        ? `${summary.profile.oposicion} · ${summary.profile.especialidad}`
        : null;
    const unreadCount = summary?.notifications.unreadCount ?? 0;
    const hasUnread = unreadCount > 0;
    const currentStreak = summary?.gamification.currentStreak ?? 0;
    const opopointsBalance = summary?.gamification.opopointsBalance ?? 0;
    const planPercent = planSummary?.today.percent ?? 0;
    const planCompleted = planSummary?.today.completedCount ?? 0;
    const planGoal = planSummary?.today.goalCount ?? 3;

    const realNudge = summary?.nextNudge ?? null;
    const realNudgeVisuals = realNudge ? NUDGE_VISUALS[realNudge.nudgeKind] : null;

    const dismissRealNudge = () => {
        setRealNudgeVisible(false);
        if (realNudge) dashboardApi.markNotificationRead(realNudge.id);
    };

    return (
        <SafeAreaView style={styles.container}>
            <StatusBar barStyle="dark-content" backgroundColor={colors.white} />

            {/* Header (dash-head) */}
            <View style={styles.header}>
                <View style={styles.avatar}>
                    <IconProfile size={37} />
                </View>
                <View>
                    <Text style={styles.greeting}>
                        <Text style={styles.greetingLight}>Hola, </Text>
                        <Text style={styles.greetingName}>{displayName}</Text>
                    </Text>
                    {oposicionLine && <Text style={styles.greetingSub}>{oposicionLine}</Text>}
                </View>
                <TouchableOpacity
                    style={styles.bell}
                    onPress={() => navigation.navigate('Notifications')}
                    activeOpacity={0.7}
                >
                    <IconBell size={22} />
                    {hasUnread && (
                        <View style={styles.bellBadge}>
                            <Text style={styles.bellBadgeText}>{unreadCount > 9 ? '9+' : unreadCount}</Text>
                        </View>
                    )}
                </TouchableOpacity>
            </View>

            {/* Cuerpo scrollable (scr-scroll) */}
            <ScrollView
                style={styles.scroll}
                contentContainerStyle={styles.body}
                showsVerticalScrollIndicator={false}
            >
                {/* ── 2.1 Widgets vivos ── */}
                <TouchableOpacity
                    style={styles.widget}
                    onPress={() => navigation.navigate('HomeHealth')}
                    activeOpacity={0.85}
                >
                    <View style={styles.widgetHead}>
                        <IconHealth size={24} />
                        <Text style={styles.widgetHeadText}>Salud</Text>
                    </View>
                    <View style={styles.healthRow}>
                        <View style={{ flex: 1 }}>
                            <Text style={styles.healthValue}>
                                77 <Text style={styles.healthUnit}>ppm</Text>
                            </Text>
                            <Text style={styles.healthStatus}>Nivel de fatiga elevado</Text>
                        </View>
                        <View style={styles.ringWrap}>
                            <ProgressRing percent={85} size={76} strokeWidth={8} arcColor={colors.statRed} />
                            <Text style={styles.ringText}>85%</Text>
                        </View>
                        <IconChevronRight size={13} />
                    </View>
                </TouchableOpacity>

                <View style={styles.grid2}>
                    <TouchableOpacity
                        style={[styles.widget, styles.widgetHalf]}
                        onPress={() => navigation.navigate('PlanningHome')}
                        activeOpacity={0.85}
                    >
                        <View style={styles.widgetHead}>
                            <IconPlan size={18} />
                            <Text style={styles.widgetHeadText}>Plan</Text>
                        </View>
                        <View style={styles.ringWrapCentered}>
                            <ProgressRing percent={planPercent} size={58} strokeWidth={7} arcColor={colors.ctaGreen} />
                            <Text style={styles.ringTextSmall}>{planPercent}%</Text>
                        </View>
                        <Text style={styles.ringCaption}>{planCompleted}/{planGoal} tests hoy</Text>
                    </TouchableOpacity>

                    <TouchableOpacity
                        style={[styles.widget, styles.widgetHalf]}
                        onPress={() => navigation.navigate('MotivationHome')}
                        activeOpacity={0.85}
                    >
                        <View style={styles.widgetHead}>
                            <IconStreak size={16} />
                            <Text style={styles.widgetHeadText}>Racha</Text>
                        </View>
                        <View style={{ alignItems: 'center' }}>
                            <Text style={styles.streakValue}>{currentStreak}</Text>
                            <Text style={styles.streakCaption}>Días seguidos</Text>
                            <Text style={styles.streakPoints}>+ {opopointsBalance} Opopoints</Text>
                        </View>
                    </TouchableOpacity>
                </View>

                <TouchableOpacity
                    style={styles.widget}
                    onPress={() => navigation.navigate('AITutor')}
                    activeOpacity={0.85}
                    accessibilityLabel="Ir al Aula Virtual con Tutor IA"
                >
                    <View style={styles.widgetHead}>
                        <IconTutor size={22} />
                        <Text style={styles.widgetHeadText}>Repaso</Text>
                        <View style={styles.chevSpacer}>
                            <IconChevronRotated size={15} />
                        </View>
                    </View>
                    <Text style={styles.tutorText}>Pregúntale al Tutor o escucha en modo podcast.</Text>
                </TouchableOpacity>

                {/* ── 2.2 Módulo Acceso rápido ── */}
                <Text style={styles.quickLabel}>CONTINÚA DONDE LO DEJASTE</Text>

                <View style={styles.quickListDivider} />
                <TouchableOpacity
                    style={styles.quickRow}
                    activeOpacity={0.7}
                    onPress={() => navigation.navigate('AITutor')}
                >
                    <View style={styles.quickIconSlot}>
                        <IconLaw size={26} />
                    </View>
                    <View style={{ flex: 1 }}>
                        <Text style={styles.quickTitle}>Última ley consultada</Text>
                        <Text style={styles.quickSubtitle}>Ley 39/2015 · art. 21</Text>
                    </View>
                    <IconChevronRight size={13} />
                </TouchableOpacity>
                <View style={styles.quickListDivider} />
                <TouchableOpacity
                    style={styles.quickRow}
                    activeOpacity={0.7}
                    onPress={() => navigation.navigate('ErrorLab')}
                >
                    <View style={styles.quickIconSlot}>
                        <IconError size={20} />
                    </View>
                    <View style={{ flex: 1 }}>
                        <Text style={styles.quickTitle}>Último error</Text>
                        <Text style={styles.quickSubtitle}>Derecho Administrativo · repasar</Text>
                    </View>
                    <IconChevronRight size={13} />
                </TouchableOpacity>
                <View style={styles.quickListDivider} />

                <View style={styles.resumeCard}>
                    <View style={{ flex: 1 }}>
                        <Text style={styles.resumeTitle}>¿Seguimos con el simulacro?</Text>
                        <Text style={styles.resumeSubtitle}>Examen 2022 · 28% completado</Text>
                    </View>
                    <TouchableOpacity
                        style={styles.resumeBtn}
                        activeOpacity={0.85}
                        onPress={() => navigation.navigate('OfficialMocks')}
                    >
                        <Text style={styles.resumeBtnText}>Reanudar</Text>
                    </TouchableOpacity>
                </View>

                {/* Bloque 9 · Factoría de Apuntes (fuera del frame Figma) */}
                <TouchableOpacity
                    style={[styles.legacyWidget, { backgroundColor: '#EFF6FF', marginTop: 22 }]}
                    onPress={() => navigation.navigate('NotesHome')}
                    activeOpacity={0.85}
                    accessibilityLabel="Ir a la Factoría de Apuntes"
                >
                    <View style={styles.widgetHead}>
                        <IconNotes />
                        <Text style={[styles.legacyWidgetHeadText, { color: '#2563EB' }]}>Mis apuntes</Text>
                        <Text style={styles.chev}>›</Text>
                    </View>
                    <Text style={styles.tutorText}>Sube PDFs o fotos y practica con preguntas generadas por IA.</Text>
                </TouchableOpacity>

                {/* Bloque 10 · Monitor BOE (fuera del frame Figma) */}
                <TouchableOpacity
                    style={[styles.legacyWidget, { backgroundColor: '#FDEBE9' }]}
                    onPress={() => navigation.navigate('BoeHome')}
                    activeOpacity={0.85}
                    accessibilityLabel="Ir al Monitor BOE"
                >
                    <View style={styles.widgetHead}>
                        <IconBoe />
                        <Text style={[styles.legacyWidgetHeadText, { color: '#E2483D' }]}>Monitor BOE</Text>
                        <View style={styles.boeliveBadge}>
                            <View style={styles.boeLiveDot} />
                            <Text style={styles.boeLiveText}>LIVE</Text>
                        </View>
                        <Text style={styles.chev}>›</Text>
                    </View>
                    <Text style={styles.tutorText}>Cambios legislativos que afectan a tu temario, al instante.</Text>
                </TouchableOpacity>

                {/* Bloque 11 · Tienda (fuera del frame Figma) */}
                <TouchableOpacity
                    style={[styles.legacyWidget, { backgroundColor: '#EDE7F6' }]}
                    onPress={() => navigation.navigate('StoreHome')}
                    activeOpacity={0.85}
                    accessibilityLabel="Ir a la Tienda OPOX"
                >
                    <View style={styles.widgetHead}>
                        <IconStore />
                        <Text style={[styles.legacyWidgetHeadText, { color: '#6C5CE7' }]}>Tienda OPOX</Text>
                        <Text style={styles.chev}>›</Text>
                    </View>
                    <Text style={styles.tutorText}>Canjea tus Opopoints por recompensas virtuales y reales.</Text>
                </TouchableOpacity>

                {/* Vista previa temporal de los nudges — quitar cuando cada motor real
                    (fatiga, estadísticas, monitor BOE) dispare el suyo */}
                <Text style={styles.demoLabel}>VISTA PREVIA · NUDGES</Text>
                <View style={styles.demoRow}>
                    <TouchableOpacity style={styles.demoPill} onPress={() => setActiveNudge('fatigue')}>
                        <Text style={styles.demoPillText}>Fatiga</Text>
                    </TouchableOpacity>
                    <TouchableOpacity style={styles.demoPill} onPress={() => setActiveNudge('academic')}>
                        <Text style={styles.demoPillText}>Tema flojo</Text>
                    </TouchableOpacity>
                    <TouchableOpacity style={styles.demoPill} onPress={() => setActiveNudge('boe')}>
                        <Text style={styles.demoPillText}>Nudge BOE</Text>
                    </TouchableOpacity>
                    <TouchableOpacity style={styles.demoPill} onPress={() => setBoeBannerVisible(true)}>
                        <Text style={styles.demoPillText}>Push BOE</Text>
                    </TouchableOpacity>
                    <TouchableOpacity style={styles.demoPill} onPress={() => setStaleAlertVisible(true)}>
                        <Text style={styles.demoPillText}>Temario desact.</Text>
                    </TouchableOpacity>
                </View>

                <View style={{ height: 70 + insets.bottom }} />
            </ScrollView>

            {/* Botón central (+) = Nuevo Test → hub de entrenamiento */}
            <TouchableOpacity
                style={[styles.fab, { bottom: 38 + insets.bottom }]}
                onPress={() => navigation.navigate('TrainingHome')}
                activeOpacity={0.85}
            >
                <Svg width={24} height={24} viewBox="0 0 24 24" fill="none">
                    <Path d="M12 5v14M5 12h14" stroke="#FFFFFF" strokeWidth={2.4} strokeLinecap="round" />
                </Svg>
            </TouchableOpacity>

            {/* Nav inferior */}
            <View style={[styles.nav, { height: 56 + insets.bottom, paddingBottom: insets.bottom }]}>
                <View style={styles.navItem}>
                    <IconNavHome active />
                    <Text style={[styles.navLabel, styles.navLabelActive]}>Inicio</Text>
                </View>
                <TouchableOpacity style={styles.navItem} onPress={() => navigation.navigate('TrainingHome')}>
                    <IconNavTraining />
                    <Text style={styles.navLabel}>Entreno</Text>
                </TouchableOpacity>
                <View style={{ width: 40 }} />
                <TouchableOpacity style={styles.navItem} onPress={() => navigation.navigate('MotivationHome')}>
                    <IconNavSocial />
                    <Text style={styles.navLabel}>Social</Text>
                </TouchableOpacity>
                <TouchableOpacity style={styles.navItem} onPress={() => navigation.navigate('Settings')}>
                    <IconNavSettings />
                    <Text style={styles.navLabel}>Ajustes</Text>
                </TouchableOpacity>
            </View>

            {nudge && (
                <NudgeModal
                    visible={!!activeNudge}
                    iconBg={nudge.iconBg}
                    icon={nudge.icon}
                    title={nudge.title}
                    description={nudge.description}
                    primaryLabel={nudge.primaryLabel}
                    secondaryLabel={nudge.secondaryLabel}
                    onPrimaryPress={() => {
                        const kind = activeNudge;
                        setActiveNudge(null);
                        if (kind === 'boe') navigation.navigate('BoeHome');
                    }}
                    onSecondaryPress={() => setActiveNudge(null)}
                />
            )}

            {/* Pop-up temario desactualizado (10.1·alerta) — en Paso 2 lo dispara dashboardApi.getSummary() → staleLawsCount */}
            <AlertCardModal
                visible={staleAlertVisible}
                iconBg="transparent"
                iconSize={80}
                icon={<StaleLawsWarningIcon />}
                title={`${staleLawsCount} ${staleLawsCount === 1 ? 'ley' : 'leyes'} de tu temario ${staleLawsCount === 1 ? 'ha cambiado' : 'han cambiado'}`}
                description="Para no estudiar contenido desfasado, revísalas y pon tu temario al día."
                primaryLabel="Revisar cambios"
                primaryColor={colors.ctaGreen}
                onPrimaryPress={() => {
                    setStaleAlertVisible(false);
                    navigation.navigate('BoeHome');
                }}
                secondaryLabel="Más tarde"
                onSecondaryPress={() => setStaleAlertVisible(false)}
            />

            {/* Banner push BOE en foreground (10.1·notif) — en Paso 2 lo dispara expo-notifications */}
            <BoeAlertBanner
                visible={boeBannerVisible}
                onDismiss={() => setBoeBannerVisible(false)}
                onPress={() => {
                    setBoeBannerVisible(false);
                    navigation.navigate('BoeHome');
                }}
            />

            {/* Nudge real pendiente del backend (2.4) — no se muestra a la vez que la demo */}
            {!nudge && realNudgeVisible && realNudge && realNudgeVisuals && (
                <NudgeModal
                    visible={realNudgeVisible}
                    iconBg={realNudgeVisuals.iconBg}
                    icon={realNudgeVisuals.icon}
                    title={realNudge.title}
                    description={realNudge.body}
                    primaryLabel={realNudge.primaryLabel || 'Entendido'}
                    secondaryLabel={realNudge.secondaryLabel || 'Cerrar'}
                    onPrimaryPress={dismissRealNudge}
                    onSecondaryPress={dismissRealNudge}
                />
            )}
        </SafeAreaView>
    );
}

